/* ============================================================================
 * TapMyCar  Hotfix  landing.html escaped apostrophes
 *
 * The previous landing patch wrote literal backslash-apostrophes (\\') into
 * the two new sections (harassment + tow operators), so phrases like
 *   "can\\'t reach you again"  and  "you\\'re the first to know"
 * rendered with visible backslashes on the live site.
 *
 * Fix: rewrites landing.html with apostrophes corrected.
 *
 * Run from project root:  node tapmycar-patch-landing-apostrophe-hotfix.js
 * Safe to re-run.
 * ==========================================================================*/
'use strict';
const fs = require('fs');
const path = require('path');

const STAMP = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
const BACKUP_DIR = 'backup-landing-apostrophe-' + STAMP;
const TARGET = path.join('public', 'landing.html');

const NEW_BODY = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"TapMyCar\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>TapMyCar — Privacy-first vehicle contact | Praman Tech LLC</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n<style>\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: 'Inter', sans-serif; background: #fff; color: #111; max-width: 430px; margin: 0 auto; }\n\n/* HERO */\n.hero { background: #FF6B00; padding: 48px 24px 40px; text-align: center; position: relative; overflow: hidden; }\n.hero-ring1 { position: absolute; width: 200px; height: 200px; border-radius: 50%; background: rgba(255,255,255,.06); right: -60px; top: -60px; }\n.hero-ring2 { position: absolute; width: 140px; height: 140px; border-radius: 50%; background: rgba(255,255,255,.04); left: -40px; bottom: -40px; }\n.hero-badge { display: inline-flex; align-items: center; gap: 6px; background: rgba(255,255,255,.2); border-radius: 99px; padding: 5px 14px; font-size: 11px; font-weight: 600; color: #fff; margin-bottom: 20px; }\n.hero-badge-dot { width: 6px; height: 6px; border-radius: 50%; background: #fff; animation: pulse 1.6s ease-in-out infinite; }\n.hero h1 { font-size: 34px; font-weight: 800; color: #fff; letter-spacing: -.6px; line-height: 1.1; margin-bottom: 12px; }\n.hero h1 span { color: rgba(255,255,255,.7); }\n.hero p { font-size: 14px; color: rgba(255,255,255,.75); line-height: 1.6; margin-bottom: 28px; max-width: 300px; margin-left: auto; margin-right: auto; }\n.hero-btns { display: flex; flex-direction: column; gap: 10px; }\n.hero-btn-primary { background: #fff; color: #FF6B00; font-size: 15px; font-weight: 800; padding: 15px 0; border-radius: 14px; text-decoration: none; display: block; box-shadow: 0 8px 24px rgba(0,0,0,.15); }\n.hero-btn-secondary { background: rgba(255,255,255,.15); color: #fff; font-size: 14px; font-weight: 600; padding: 13px 0; border-radius: 14px; text-decoration: none; display: block; border: 1.5px solid rgba(255,255,255,.3); }\n\n/* SECTIONS */\n.section { padding: 36px 24px; }\n.section-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: #FF6B00; margin-bottom: 8px; }\n.section h2 { font-size: 24px; font-weight: 800; color: #111; margin-bottom: 6px; line-height: 1.2; }\n.section p { font-size: 13px; color: #6B7280; line-height: 1.6; margin-bottom: 24px; }\n\n/* RISK CARDS */\n.risk-grid { display: flex; flex-direction: column; gap: 10px; }\n.risk { display: flex; gap: 12px; align-items: flex-start; background: #FEF2F2; border-radius: 12px; padding: 14px; border: .5px solid #FECACA; }\n.risk-icon { width: 32px; height: 32px; border-radius: 8px; background: #FEE2E2; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n.risk-icon svg { width: 16px; height: 16px; stroke: #DC2626; fill: none; stroke-width: 2; stroke-linecap: round; }\n.risk h3 { font-size: 13px; font-weight: 700; color: #991B1B; margin-bottom: 2px; }\n.risk p { font-size: 11px; color: #B91C1C; line-height: 1.5; margin-bottom: 0; }\n\n/* SOLUTION CARDS */\n.sol-grid { display: flex; flex-direction: column; gap: 10px; }\n.sol { display: flex; gap: 12px; align-items: flex-start; background: #F0FDF4; border-radius: 12px; padding: 14px; border: .5px solid #BBF7D0; }\n.sol-icon { width: 32px; height: 32px; border-radius: 8px; background: #DCFCE7; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n.sol-icon svg { width: 16px; height: 16px; stroke: #16A34A; fill: none; stroke-width: 2; stroke-linecap: round; }\n.sol h3 { font-size: 13px; font-weight: 700; color: #166534; margin-bottom: 2px; }\n.sol p { font-size: 11px; color: #15803D; line-height: 1.5; margin-bottom: 0; }\n\n/* TMC_STICKER_FLASH_FIX: hide hero sticker on first paint until JS decides */\n#tmc-hero-sticker.tmc-pre-hidden { visibility: hidden; }\n\n/* TMC_BRANDING: hero sticker scene + stats card + marquee + step ring */\n.tmc-scene { position: relative; width: 220px; height: 220px; margin: 6px auto 22px; perspective: 1000px; z-index: 2; }\n.tmc-scene-glow { position: absolute; inset: -20px; border-radius: 50%; background: radial-gradient(circle, rgba(255,255,255,.40) 0%, transparent 60%); filter: blur(28px); animation: tmcSceneGlow 3.2s ease-in-out infinite alternate; }\n@keyframes tmcSceneGlow { from { opacity: .5; transform: scale(.92); } to { opacity: 1; transform: scale(1.1); } }\n.tmc-scene-ring { position: absolute; inset: -10px; border-radius: 50%; border: 2px solid rgba(255,255,255,.28); animation: tmcRingSpin 20s linear infinite; }\n.tmc-scene-ring::before { content: ''; position: absolute; width: 14px; height: 14px; border-radius: 50%; background: #fff; top: -7px; left: 50%; margin-left: -7px; box-shadow: 0 0 20px #fff, 0 0 40px rgba(255,255,255,.6); }\n.tmc-scene-ring2 { position: absolute; inset: 6px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.4); animation: tmcRingSpin 30s linear infinite reverse; }\n@keyframes tmcRingSpin { to { transform: rotate(360deg); } }\n.tmc-sticker-3d { position: absolute; inset: 34px; border-radius: 30px; background: linear-gradient(135deg,#fff 0%,#f0f0f0 100%); box-shadow: 0 0 0 4px #FF6B00, 0 22px 50px rgba(0,0,0,.35), 0 12px 28px rgba(255,107,0,.5), inset 0 2px 0 rgba(255,255,255,.85); display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; transform-style: preserve-3d; animation: tmcStickerFloat 6s ease-in-out infinite; padding: 10px; }\n@keyframes tmcStickerFloat { 0%,100% { transform: rotateY(-32deg) rotateX(14deg) translateY(0); } 50% { transform: rotateY(32deg) rotateX(-10deg) translateY(-10px); } }\n.tmc-scene:hover .tmc-sticker-3d { animation-play-state: paused; }\n.tmc-scene { cursor: pointer; }\n.tmc-scene:hover .tmc-scene-glow { animation: none; opacity: 1; transform: scale(1.2); }\n.tmc-scene:hover .tmc-scene-ring { animation-duration: 6s; }\n.tmc-scene:hover .tmc-scene-ring2 { animation-duration: 9s; }\n.tmc-sticker-3d img { width: 100%; height: 100%; object-fit: contain; display: block; }\n.tmc-sticker-3d-fallback { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }\n.tmc-sticker-3d-fallback svg { width: 60px; height: 60px; }\n.tmc-sticker-3d-fallback .l1 { font-size: 12px; font-weight: 900; color: #111; letter-spacing: 1.5px; }\n.tmc-sticker-3d-fallback .l2 { font-size: 8px; color: #FF6B00; font-weight: 700; letter-spacing: 2px; }\n\n.tmc-stats { display: grid; grid-template-columns: repeat(3, 1fr); padding: 22px 22px; background: #fff; position: relative; margin-top: -22px; z-index: 4; border-top-left-radius: 24px; border-top-right-radius: 24px; box-shadow: 0 -8px 24px rgba(0,0,0,.06); }\n.tmc-stat { text-align: center; position: relative; }\n.tmc-stat:not(:last-child)::after { content: ''; position: absolute; right: 0; top: 14%; bottom: 14%; width: 1px; background: #F0F0F0; }\n.tmc-stat-n { font-size: 20px; font-weight: 900; color: #FF6B00; letter-spacing: -.5px; line-height: 1.1; }\n.tmc-stat-l { font-size: 9px; color: #6B7280; text-transform: uppercase; letter-spacing: .8px; font-weight: 600; margin-top: 4px; }\n\n.tmc-trust { background: #FFF7ED; border-top: 1px solid #FED7AA; border-bottom: 1px solid #FED7AA; overflow: hidden; padding: 11px 0; position: relative; }\n.tmc-trust::before, .tmc-trust::after { content: ''; position: absolute; top: 0; bottom: 0; width: 40px; z-index: 2; pointer-events: none; }\n.tmc-trust::before { left: 0; background: linear-gradient(90deg, #FFF7ED, transparent); }\n.tmc-trust::after { right: 0; background: linear-gradient(-90deg, #FFF7ED, transparent); }\n.tmc-trust-track { display: flex; gap: 28px; animation: tmcMarquee 22s linear infinite; white-space: nowrap; width: max-content; }\n@keyframes tmcMarquee { to { transform: translateX(-50%); } }\n.tmc-trust-item { display: inline-flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 700; color: #9A3412; }\n.tmc-trust-item svg { width: 13px; height: 13px; }\n\n/* Pulsing ring around How it works step numbers */\n.step .step-num { position: relative; }\n.step .step-num::after { content: ''; position: absolute; inset: -4px; border-radius: 14px; background: linear-gradient(135deg, #FF6B00, #FF9540); opacity: .25; z-index: -1; animation: tmcRingPulse 2s ease-in-out infinite; }\n@keyframes tmcRingPulse { 0%,100% { transform: scale(1); opacity: .25; } 50% { transform: scale(1.35); opacity: 0; } }\n\n/* TMC_BREATHE: continuous slow breathing on every risk/sol/feat card */\n.risk, .sol, .feat { will-change: transform, box-shadow; transform: translateY(0); }\n\n.risk { box-shadow: 0 2px 6px rgba(220,38,38,.06); animation: tmcBreatheRed 10s ease-in-out infinite; }\n.risk:nth-child(2) { animation-delay: -2.5s; }\n.risk:nth-child(3) { animation-delay: -5s; }\n.risk:nth-child(4) { animation-delay: -7.5s; }\n.risk-icon { animation: tmcBreatheIconRed 10s ease-in-out infinite; will-change: transform; }\n.risk:nth-child(2) .risk-icon { animation-delay: -2.5s; }\n.risk:nth-child(3) .risk-icon { animation-delay: -5s; }\n.risk:nth-child(4) .risk-icon { animation-delay: -7.5s; }\n@keyframes tmcBreatheRed {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(220,38,38,.06); }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(220,38,38,.22), 0 4px 10px rgba(220,38,38,.08); }\n}\n@keyframes tmcBreatheIconRed { 0%,100% { transform: scale(1) rotate(0); } 50% { transform: scale(1.08) rotate(-4deg); } }\n\n.sol { box-shadow: 0 2px 6px rgba(22,163,74,.06); animation: tmcBreatheGreen 11s ease-in-out infinite; }\n.sol:nth-child(2) { animation-delay: -2.75s; }\n.sol:nth-child(3) { animation-delay: -5.5s; }\n.sol:nth-child(4) { animation-delay: -8.25s; }\n.sol-icon { animation: tmcBreatheIconGreen 11s ease-in-out infinite; will-change: transform; }\n.sol:nth-child(2) .sol-icon { animation-delay: -2.75s; }\n.sol:nth-child(3) .sol-icon { animation-delay: -5.5s; }\n.sol:nth-child(4) .sol-icon { animation-delay: -8.25s; }\n@keyframes tmcBreatheGreen {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(22,163,74,.06); }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(22,163,74,.22), 0 4px 10px rgba(22,163,74,.08); }\n}\n@keyframes tmcBreatheIconGreen { 0%,100% { transform: scale(1) rotate(0); } 50% { transform: scale(1.08) rotate(4deg); } }\n\n.feat { box-shadow: 0 2px 6px rgba(255,107,0,.05); animation: tmcBreatheOrange 12s ease-in-out infinite; }\n.feat:nth-child(2) { animation-delay: -2s; }\n.feat:nth-child(3) { animation-delay: -4s; }\n.feat:nth-child(4) { animation-delay: -6s; }\n.feat:nth-child(5) { animation-delay: -8s; }\n.feat:nth-child(6) { animation-delay: -10s; }\n.feat-icon { animation: tmcBreatheIconOrange 12s ease-in-out infinite; will-change: transform, background; }\n.feat:nth-child(2) .feat-icon { animation-delay: -2s; }\n.feat:nth-child(3) .feat-icon { animation-delay: -4s; }\n.feat:nth-child(4) .feat-icon { animation-delay: -6s; }\n.feat:nth-child(5) .feat-icon { animation-delay: -8s; }\n.feat:nth-child(6) .feat-icon { animation-delay: -10s; }\n@keyframes tmcBreatheOrange {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(255,107,0,.05); border-color: #E5E7EB; }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(255,107,0,.22), 0 4px 10px rgba(255,107,0,.08); border-color: #FED7AA; }\n}\n@keyframes tmcBreatheIconOrange { 0%,100% { transform: scale(1) rotate(0); background: #FFF3EC; } 50% { transform: scale(1.1) rotate(-5deg); background: #FED7AA; } }\n\n/* Respect reduced-motion preference */\n@media (prefers-reduced-motion: reduce) {\n  .risk, .sol, .feat, .risk-icon, .sol-icon, .feat-icon { animation: none !important; }\n}\n\n/* HOW IT WORKS */\n.steps { display: flex; flex-direction: column; gap: 16px; }\n.step { display: flex; gap: 14px; align-items: flex-start; }\n.step-num { width: 36px; height: 36px; border-radius: 10px; background: #FF6B00; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 800; color: #fff; flex-shrink: 0; }\n.step-body h3 { font-size: 14px; font-weight: 700; color: #111; margin-bottom: 3px; }\n.step-body p { font-size: 12px; color: #6B7280; line-height: 1.5; margin-bottom: 0; }\n\n/* FEATURES */\n.features-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 8px; }\n.feat { background: #F9FAFB; border-radius: 14px; padding: 16px; border: .5px solid #E5E7EB; }\n.feat-icon { width: 36px; height: 36px; border-radius: 10px; background: #FFF3EC; display: flex; align-items: center; justify-content: center; margin-bottom: 10px; }\n.feat-icon svg { width: 18px; height: 18px; stroke: #FF6B00; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.feat h3 { font-size: 13px; font-weight: 700; color: #111; margin-bottom: 4px; }\n.feat p { font-size: 11px; color: #6B7280; line-height: 1.5; margin-bottom: 0; }\n\n/* PRICING */\n.pricing-card { border: 2px solid #FF6B00; border-radius: 18px; padding: 20px; margin-bottom: 12px; }\n.pricing-card h3 { font-size: 18px; font-weight: 800; color: #111; margin-bottom: 4px; }\n.pricing-price { font-size: 32px; font-weight: 800; color: #FF6B00; margin-bottom: 4px; }\n.pricing-price span { font-size: 14px; color: #6B7280; font-weight: 400; }\n.pricing-desc { font-size: 12px; color: #6B7280; margin-bottom: 16px; }\n.pricing-features { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }\n.pf { display: flex; align-items: center; gap: 8px; font-size: 12px; color: #111; }\n.pf-dot { width: 6px; height: 6px; border-radius: 1px; background: #FF6B00; flex-shrink: 0; }\n\n/* LEARN MORE BUTTON */\n.learn-btn { display: flex; align-items: center; justify-content: center; gap: 6px; background: #FFF3EC; color: #FF6B00; font-size: 13px; font-weight: 700; padding: 12px 0; border-radius: 12px; text-decoration: none; border: 1.5px solid #FFE4CC; margin-top: 16px; }\n\n/* APP DOWNLOAD BANNER */\n.app-banner { background: #111; padding: 24px; text-align: center; }\n.app-banner h3 { font-size: 18px; font-weight: 800; color: #fff; margin-bottom: 6px; }\n.app-banner p { font-size: 12px; color: #9CA3AF; margin-bottom: 16px; line-height: 1.5; }\n.app-btn { background: #FF6B00; color: #fff; font-size: 14px; font-weight: 700; padding: 14px 0; border-radius: 13px; text-decoration: none; display: block; margin-bottom: 8px; }\n.app-sub { font-size: 10px; color: #6B7280; }\n\n/* TESTIMONIAL */\n.testimonial { background: #F9FAFB; border-radius: 16px; padding: 20px; border: .5px solid #E5E7EB; margin-top: 8px; }\n.testimonial p { font-size: 14px; color: #111; line-height: 1.6; font-style: italic; margin-bottom: 12px; }\n.test-author { display: flex; align-items: center; gap: 10px; }\n.test-av { width: 36px; height: 36px; border-radius: 50%; background: #FF6B00; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; color: #fff; }\n.test-name { font-size: 13px; font-weight: 700; color: #111; }\n.test-sub { font-size: 11px; color: #6B7280; }\n\n/* CTA */\n.cta { background: #FF6B00; padding: 36px 24px; text-align: center; }\n.cta h2 { font-size: 24px; font-weight: 800; color: #fff; margin-bottom: 8px; }\n.cta p { font-size: 13px; color: rgba(255,255,255,.8); margin-bottom: 24px; line-height: 1.6; }\n.cta-btn { background: #fff; color: #FF6B00; font-size: 15px; font-weight: 800; padding: 15px 0; border-radius: 14px; text-decoration: none; display: block; }\n\n/* FOOTER */\n.footer { padding: 20px 24px; border-top: .5px solid #E5E7EB; text-align: center; }\n.footer p { font-size: 11px; color: #9CA3AF; }\n.footer a { color: #FF6B00; text-decoration: none; font-weight: 600; }\n\n@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.45;transform:scale(.75)} }\n\n/* TMC_V3BOLD: mobile-friendly always-on animations + tap effects */\n@keyframes tmcCardFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }\n@keyframes tmcIconBreath { 0%,100% { transform: scale(1) rotate(0deg); } 50% { transform: scale(1.06) rotate(-2deg); } }\n@keyframes tmcSweep { 0% { left: -120%; } 60%, 100% { left: 150%; } }\n@keyframes tmcDoubleRing { 0%,100% { transform: scale(1); opacity: .3; } 50% { transform: scale(1.4); opacity: 0; } }\n\n/* HERO buttons  3D press + shimmer  always works on mobile */\n.hero-btn-primary {\n  background: linear-gradient(135deg, #fff 0%, #fff5ee 100%) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.55), 0 14px 30px rgba(0,0,0,.22) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s cubic-bezier(.2,.8,.2,1), box-shadow .18s ease;\n}\n.hero-btn-primary::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,107,0,.4) 50%, transparent 70%);\n  animation: tmcSweep 2.6s ease-in-out infinite;\n  pointer-events: none;\n}\n.hero-btn-primary:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.55), 0 6px 14px rgba(0,0,0,.18) !important; }\n.hero-btn-secondary {\n  transition: background .25s ease, border-color .25s ease, transform .18s ease;\n  position: relative; overflow: hidden;\n}\n.hero-btn-secondary:active { background: rgba(255,255,255,.35); transform: translateY(2px); }\n\n/* NAV button (Get Started) */\n.tmc-nav-cta { transition: transform .2s ease, box-shadow .2s ease !important; box-shadow: 0 6px 16px rgba(255,107,0,.4) !important; }\n.tmc-nav-cta:active { transform: translateY(2px); box-shadow: 0 2px 8px rgba(255,107,0,.45) !important; }\n\n/* RISK cards  float + tap press */\n.risk {\n  animation: tmcCardFloat 4s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 6px 16px rgba(220,38,38,.08);\n}\n.risk:nth-child(1) { animation-delay: 0s; }\n.risk:nth-child(2) { animation-delay: -1s; }\n.risk:nth-child(3) { animation-delay: -2s; }\n.risk:nth-child(4) { animation-delay: -3s; }\n.risk:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(220,38,38,.18) !important; }\n.risk-icon { animation: tmcIconBreath 4s ease-in-out infinite; }\n.risk:nth-child(2) .risk-icon { animation-delay: -1s; }\n.risk:nth-child(3) .risk-icon { animation-delay: -2s; }\n.risk:nth-child(4) .risk-icon { animation-delay: -3s; }\n\n/* SOLUTION cards */\n.sol {\n  animation: tmcCardFloat 4.5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 6px 16px rgba(22,163,74,.08);\n}\n.sol:nth-child(1) { animation-delay: -.5s; }\n.sol:nth-child(2) { animation-delay: -1.5s; }\n.sol:nth-child(3) { animation-delay: -2.5s; }\n.sol:nth-child(4) { animation-delay: -3.5s; }\n.sol:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(22,163,74,.18) !important; }\n.sol-icon { animation: tmcIconBreath 4.5s ease-in-out infinite; }\n.sol:nth-child(2) .sol-icon { animation-delay: -1.5s; }\n.sol:nth-child(3) .sol-icon { animation-delay: -2.5s; }\n.sol:nth-child(4) .sol-icon { animation-delay: -3.5s; }\n\n/* STEP NUMBERS  double pulsing ring */\n.step .step-num {\n  position: relative;\n  background: linear-gradient(135deg, #FF6B00, #FF9540) !important;\n  box-shadow: 0 8px 20px rgba(255,107,0,.5), inset 0 2px 0 rgba(255,255,255,.35) !important;\n}\n.step .step-num::before {\n  content: ''; position: absolute; inset: -5px; border-radius: 15px;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .3; z-index: -1;\n  animation: tmcDoubleRing 2s ease-in-out infinite;\n}\n.step .step-num::after {\n  content: ''; position: absolute; inset: -10px; border-radius: 18px;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .15; z-index: -2;\n  animation: tmcDoubleRing 2s ease-in-out infinite .5s;\n}\n\n/* eTag toggle */\n#etag-toggle { transition: transform .18s ease, box-shadow .18s ease, background .25s ease !important; cursor: pointer; }\n#etag-toggle:active { transform: scale(.98) !important; background: #FFF7ED !important; }\n\n/* LEARN button (How TapMyCar solves this) */\n.learn-btn { transition: transform .18s ease, box-shadow .18s ease, background .25s ease, gap .25s ease !important; position: relative; overflow: hidden; }\n.learn-btn:active { transform: translateY(2px); background: #FFE0CC !important; }\n\n/* FEATURES grid */\n.feat {\n  animation: tmcCardFloat 5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 4px 12px rgba(0,0,0,.04);\n}\n.feat:nth-child(1) { animation-delay: 0s; }\n.feat:nth-child(2) { animation-delay: -1.25s; }\n.feat:nth-child(3) { animation-delay: -2.5s; }\n.feat:nth-child(4) { animation-delay: -3.75s; }\n.feat:nth-child(5) { animation-delay: -5s; }\n.feat:nth-child(6) { animation-delay: -6.25s; }\n.feat:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(255,107,0,.18) !important; }\n.feat-icon { animation: tmcIconBreath 5s ease-in-out infinite; }\n\n/* PRICING cards */\n.pricing-card {\n  transition: transform .2s ease, box-shadow .2s ease !important;\n  cursor: pointer;\n  position: relative; overflow: hidden;\n}\n.pricing-card:active { transform: scale(.98) !important; }\n\n/* PRICING button (Get Standard / Get Premium / Get free eTag) */\n.tmc-cta-orange {\n  background: linear-gradient(135deg, #FF6B00, #FF8420) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.45), 0 12px 28px rgba(255,107,0,.4) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.tmc-cta-orange::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);\n  animation: tmcSweep 3s ease-in-out infinite;\n  pointer-events: none;\n}\n.tmc-cta-orange:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.45), 0 6px 14px rgba(255,107,0,.3) !important; }\n\n/* APP BANNER button */\n.app-btn {\n  background: linear-gradient(135deg, #FF6B00, #FF8420) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.5), 0 14px 30px rgba(255,107,0,.4) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.app-btn::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);\n  animation: tmcSweep 3s ease-in-out infinite;\n  pointer-events: none;\n}\n.app-btn:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.5), 0 6px 14px rgba(255,107,0,.3) !important; }\n\n/* TESTIMONIAL card */\n.testimonial {\n  animation: tmcCardFloat 5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  position: relative; overflow: hidden;\n}\n.testimonial::before {\n  content: '\\201C'; position: absolute; top: -8px; right: 12px;\n  font-family: Georgia, serif; font-size: 80px; color: #FF6B00;\n  opacity: .15; pointer-events: none; line-height: 1;\n}\n.testimonial:active { transform: scale(.98) !important; }\n.testimonial > * { position: relative; z-index: 1; }\n.test-av { box-shadow: 0 4px 12px rgba(255,107,0,.4); }\n\n/* FINAL CTA button  bigger 3D press */\n.cta-btn {\n  background: linear-gradient(135deg, #fff 0%, #fff5ee 100%) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.55), 0 16px 36px rgba(0,0,0,.28) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.cta-btn::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,107,0,.4) 50%, transparent 70%);\n  animation: tmcSweep 2.8s ease-in-out infinite;\n  pointer-events: none;\n}\n.cta-btn:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.55), 0 6px 16px rgba(0,0,0,.2) !important; }\n\n/* eTag activation step circles  pulsing rings */\n.etag-step-num {\n  position: relative;\n  background: linear-gradient(135deg, #FF6B00, #FF9540) !important;\n  box-shadow: 0 4px 10px rgba(255,107,0,.45) !important;\n}\n.etag-step-num::before {\n  content: ''; position: absolute; inset: -3px; border-radius: 50%;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .3; z-index: -1;\n  animation: tmcDoubleRing 2.2s ease-in-out infinite;\n}\n</style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"TapMyCar — Privacy-first vehicle contact | Praman Tech LLC\">\n<meta property=\"og:description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/landing.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"TapMyCar — Privacy-first vehicle contact | Praman Tech LLC\">\n<meta name=\"twitter:description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n</head>\n<body class=\"wide-page\">\n\n<!-- NAV -->\n<div style=\"display:flex;align-items:center;justify-content:space-between;padding:14px 24px;border-bottom:.5px solid #E5E7EB;position:sticky;top:0;background:#fff;z-index:100\">\n  <a href=\"/landing.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;gap:12px;text-decoration:none;font-size:30px;font-weight:900;color:#111;letter-spacing:-2.5px;line-height:1\"><img src=\"/logo.png\" alt=\"\" style=\"height:52px;width:auto;display:block\"><span style=\"white-space:nowrap;display:inline-block\">Tap<span style=\"color:#FF6B00\">My</span>Car</span></a>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" style=\"background:#FF6B00;color:#fff;font-size:12px;font-weight:700;padding:8px 16px;border-radius:10px;text-decoration:none\" class=\"tmc-nav-cta\">Get started</a>\n</div>\n\n<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-ring1\"></div>\n  <div class=\"hero-ring2\"></div>\n  <div class=\"hero-badge\"><div class=\"hero-badge-dot\"></div>Privacy + Safety  No app needed to contact</div>\n  <h1>Privacy for you.<br><span>Safety</span> for your car.</h1>\n  <p>Your car is always protected. Your identity is never exposed. Anyone can reach you  without ever seeing your real number.</p>\n  <!-- TMC_BRANDING 3D sticker scene -->\n  <div class=\"tmc-scene\" id=\"tmc-hero-scene\">\n    <div class=\"tmc-scene-glow\"></div>\n    <div class=\"tmc-scene-ring\"></div>\n    <div class=\"tmc-scene-ring2\"></div>\n    <div class=\"tmc-sticker-3d tmc-pre-hidden\" id=\"tmc-hero-sticker\">\n      <div class=\"tmc-sticker-3d-fallback\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FF6B00\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"2\"/><path d=\"M16.24 7.76a6 6 0 0 1 0 8.49m-8.48-.01a6 6 0 0 1 0-8.49m11.31-2.82a10 10 0 0 1 0 14.14m-14.14 0a10 10 0 0 1 0-14.14\"/></svg>\n        <div class=\"l1\">TAPMYCAR</div>\n        <div class=\"l2\">SCAN OR TAP</div>\n      </div>\n    </div>\n  </div>\n  <div class=\"hero-btns\">\n    <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"hero-btn-primary\">Explore TapMyCar</a>\n<a href=\"/why.html\" class=\"hero-btn-secondary\">Why do I need this?</a>  </div>\n</div>\n\n<!-- TMC_BRANDING stats card peeking up over hero -->\n<div class=\"tmc-stats\">\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">Very</div><div class=\"tmc-stat-l\">Private</div></div>\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">Always</div><div class=\"tmc-stat-l\">On</div></div>\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">2s</div><div class=\"tmc-stat-l\">To reach you</div></div>\n</div>\n\n<!-- TMC_BRANDING trusted-by marquee -->\n<div class=\"tmc-trust\">\n  <div class=\"tmc-trust-track\">\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Masked calling</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Privacy by design</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> NFC + QR sticker</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> No app needed</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Masked calling</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Privacy by design</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> NFC + QR sticker</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> No app needed</span>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- THE PROBLEM  WHY YOU NEED THIS -->\n<div class=\"section\" id=\"why\">\n  <div class=\"section-label\">The problem</div>\n  <h2>Your car is vulnerable right now.</h2>\n  <p>Think about it  what happens when your car needs attention and you're not there?</p>\n  <div class=\"risk-grid\">\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></div>\n      <div><h3>Hit and run</h3><p>Someone damages your parked car. No way to reach you. They drive away.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07\"/><path d=\"M3.59 1.17A2 2 0 0 0 1.61 3.38 19.79 19.79 0 0 0 12 21a19.79 19.79 0 0 0 4.69-1.07\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg></div>\n      <div><h3>Number exposed</h3><p>You leave your phone number on the dashboard. Anyone can copy it, call you, or misuse it.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg></div>\n      <div><h3>Towed away</h3><p>You're double-parked for 5 minutes. Nobody can warn you. Your car gets towed.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/></svg></div>\n      <div><h3>Headlights on</h3><p>Battery drains overnight because no one could alert you in time.</p></div>\n    </div>\n  </div>\n  <a href=\"#solution\" class=\"learn-btn\">How TapMyCar solves this </a>\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- THE SOLUTION -->\n<div class=\"section\" id=\"solution\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">The solution</div>\n  <h2>TapMyCar protects both.</h2>\n  <p>One smart tag on your car. Total privacy for you. Total safety for your vehicle.</p>\n  <div class=\"sol-grid\">\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n      <div><h3>Your number stays hidden</h3><p>Every call is masked. Strangers never see your real phone number. Ever.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg></div>\n      <div><h3>Instant contact</h3><p>Anyone scans your tag and reaches you in seconds. No app needed on their end.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n      <div><h3>Every scan logged</h3><p>See who scanned, when, and where. Full awareness of your vehicle's activity.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div>\n      <div><h3>You screen every call</h3><p>Hear who's calling before you speak. Press 1 for auto-reply. Press 2 to connect.</p></div>\n    </div>\n  </div>\n</div>\n\n<!-- TMC_LAND_OBJECTIONS: address common concerns after seeing the solution -->\n<div class=\"chev\"></div>\n\n<div class=\"sec\">\n  <div class=\"sec-label\">Common questions</div>\n  <h2>What if someone abuses the system?</h2>\n  <p>Your real number stays hidden no matter what  so a stranger calling repeatedly never has a way to follow you outside TapMyCar.</p>\n  <div style=\"background:#F0F9FF;border:1px solid #BAE6FD;border-radius:14px;padding:16px;margin-top:14px;display:flex;gap:12px;align-items:flex-start\">\n    <div style=\"width:36px;height:36px;border-radius:10px;background:#E0F2FE;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0369A1\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><polyline points=\"9 12 11 14 15 10\"/></svg>\n    </div>\n    <div>\n      <div style=\"font-size:14px;font-weight:800;color:#0C4A6E;margin-bottom:4px\">Worried about repeat calls or harassment?</div>\n      <div style=\"font-size:12px;color:#075985;line-height:1.6\">Every call is logged with timestamp and routed through a masked number. <strong>One tap blocks any number</strong>  the harasser can't reach you again, and because they never had your real number to begin with, they can't find you outside our system. You can screen first, decline, or report.</div>\n    </div>\n  </div>\n</div>\n\n<div class=\"sec\">\n  <div class=\"sec-label\">Built with tow operators in mind</div>\n  <h2>When your car is moved, you're the first to know.</h2>\n  <p>Tow operators care about getting drivers reunited with their cars. With TapMyCar, that becomes effortless.</p>\n  <div style=\"background:#FFF7ED;border:1px solid #FED7AA;border-radius:14px;padding:16px;margin-top:14px;display:flex;gap:12px;align-items:flex-start\">\n    <div style=\"width:36px;height:36px;border-radius:10px;background:#FFE4CC;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5\"/><path d=\"M21 3l-7 7\"/><path d=\"M3 21l7-7\"/><path d=\"M3 16v5h5\"/></svg>\n    </div>\n    <div>\n      <div style=\"font-size:14px;font-weight:800;color:#7C2D12;margin-bottom:4px\">Helping tow professionals do their job faster</div>\n      <div style=\"font-size:12px;color:#9A3412;line-height:1.6\">Tow operators tap your sticker and send a fast pre-filled message: <strong>where the car was taken, the lot address, and who to call</strong>. You get notified in seconds, not hours. <span style=\"color:#7C2D12;font-weight:700\">We partner with tow companies to make recoveries faster and less stressful  for everyone.</span></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- HOW IT WORKS -->\n<div class=\"section\">\n  <!-- TMC_HOWITWORKS_PHYSICAL -->\n  <div class=\"section-label\">How it works</div>\n  <h2>Simple as scan, call, done.</h2>\n  <p>Order your TapMyCar NFC sticker. Place it on your windshield. Stay reachable while your number stays hidden.</p>\n  <div class=\"steps\">\n    <div class=\"step\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-body\">\n        <h3>Order your TapMyCar sticker</h3>\n        <p>Pick Standard or Premium. Your physical NFC + QR sticker ships to your door within a few days.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-body\">\n        <h3>Stick it on your windshield</h3>\n        <p>Peel and place inside the windshield. Activates in seconds  no app needed for people scanning it.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">3</div>\n      <div class=\"step-body\">\n        <h3>Someone scans  you get a private call</h3>\n        <p>A stranger taps their phone on the sticker or scans the QR. The call routes through TapMyCar  your real number is never shown.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">4</div>\n      <div class=\"step-body\">\n        <h3>You decide what happens</h3>\n        <p>Hear who is calling first. Press 1 to send an auto-reply. Press 2 to speak directly. Decline anytime  you stay in full control.</p>\n      </div>\n    </div>\n  </div>\n\n  <div style=\"margin-top:24px;padding:16px 18px;background:#F9FAFB;border:1px solid #E5E7EB;border-radius:14px;cursor:pointer;transition:background .2s ease\" id=\"etag-toggle\" onclick=\"(function(){var b=document.getElementById('etag-box');var c=document.getElementById('etag-chev');var open=b.style.display==='block';b.style.display=open?'none':'block';c.style.transform=open?'rotate(0deg)':'rotate(180deg)';})()\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n      <div>\n        <div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:2px\">Want the free digital eTag instead?</div>\n        <div style=\"font-size:12px;color:#6B7280\">No card needed. Get started in 2 minutes  perfect for trying it out.</div>\n      </div>\n      <svg id=\"etag-chev\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FF6B00\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:0 0 18px;transition:transform .25s ease\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n    </div>\n    <div id=\"etag-box\" style=\"display:none;margin-top:14px;padding-top:14px;border-top:1px solid #E5E7EB\">\n      <div style=\"font-size:12px;color:#6B7280;line-height:1.6;margin-bottom:12px\">The eTag gives you a downloadable QR code you can print and stick anywhere. Calls still route through TapMyCar  your number stays hidden, just like the physical sticker.</div>\n      <div style=\"display:flex;flex-direction:column;gap:10px\">\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">1</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Sign up free</div><div style=\"font-size:12px;color:#6B7280\">No credit card. Pick the eTag plan during signup.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">2</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Download your QR</div><div style=\"font-size:12px;color:#6B7280\">Your unique TapMyCar QR is generated instantly. Print it on paper or a sticker.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">3</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Stick it on your windshield</div><div style=\"font-size:12px;color:#6B7280\">Any visible spot inside the windshield works. Anyone can scan it with a phone.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">4</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Receive private calls</div><div style=\"font-size:12px;color:#6B7280\">Same masked call system as the physical sticker. Your real number is never exposed.</div></div>\n        </div>\n      </div>\n      <a href=\"/pricing.html\" style=\"display:inline-block;margin-top:14px;font-size:12px;font-weight:700;color:#FF6B00;text-decoration:none\">Get the free eTag </a>\n    </div>\n  </div>\n\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- APP DOWNLOAD BANNER -->\n<div class=\"app-banner\">\n  <div style=\"width:50px;height:50px;border-radius:14px;background:#FF6B00;margin:0 auto 12px;display:flex;align-items:center;justify-content:center\">\n    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n  </div>\n  <h3>Get the TapMyCar App</h3>\n  <p>Manage your tag, view scan history, control your privacy  all from your phone.</p>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"app-btn\">Download Free </a>\n  <div class=\"app-sub\">Available on iOS, Android & Web  Free to start</div>\n</div>\n\n<!-- FEATURES -->\n<div class=\"section\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">Features</div>\n  <h2>Built for privacy and safety.</h2>\n  <div class=\"features-grid\">\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n      <h3>Masked calls</h3>\n      <p>Your real number is never revealed to anyone.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg></div>\n      <h3>QR + NFC tag</h3>\n      <p>Digital QR free. Physical NFC sticker ships on activation.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 0 1-3.46 0\"/></svg></div>\n      <h3>Scan alerts</h3>\n      <p>Get notified instantly when someone scans your tag.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg></div>\n      <h3>Voice screening</h3>\n      <p>Screen calls before speaking to any stranger.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n      <h3>Scan history</h3>\n      <p>See every scan with timestamp and location.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg></div>\n      <h3>Always on</h3>\n      <p>Your tag works 24/7 even when your phone is off.</p>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- PRICING -->\n<div class=\"section\" style=\"background:#F9FAFB;padding:36px 24px\">\n  <div class=\"section-label\">See it in action</div>\n  <h2 style=\"margin-bottom:20px\">Watch how TapMyCar works.</h2>\n  <div data-tmc-reel=\"demo\" data-tmc-label=\"\"></div>\n</div>\n\n<div class=\"chev\"></div>\n\n<div class=\"section\">\n  <div class=\"section-label\">Pricing</div>\n  <h2>Start free. Upgrade when ready.</h2>\n  <p>No hidden fees. Cancel anytime before day 30.</p>\n\n  <div class=\"pricing-card\">\n    <div style=\"display:inline-block;background:#FF6B00;color:#fff;font-size:10px;font-weight:700;padding:3px 10px;border-radius:99px;margin-bottom:8px\">Most popular</div>\n    <h3>Standard</h3>\n    <div class=\"pricing-price\">$9.99 <span>+ $9.99/yr</span></div>\n    <div class=\"pricing-desc\">1 vehicle · physical NFC + QR sticker ships home</div>\n    <div class=\"pricing-features\">\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Physical sticker ships to your home</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>10 masked calls per month</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>SMS alert on every scan</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Voice screening system</div>\n    </div>\n    <a href=\"/register.html\" style=\"background:#FF6B00;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get Standard</a>\n  </div>\n\n  <div class=\"pricing-card\" style=\"border-color:#1A1A1A;background:#FAFAFA\">\n    <div style=\"display:inline-block;background:#1A1A1A;color:#fff;font-size:10px;font-weight:700;padding:3px 10px;border-radius:99px;margin-bottom:8px\">Best for families</div>\n    <h3>Premium</h3>\n    <div class=\"pricing-price\">$24.99 <span>+ $19.99/yr</span></div>\n    <div class=\"pricing-desc\">3 physical stickers · protect your whole family</div>\n    <div class=\"pricing-features\">\n      <div class=\"pf\"><div class=\"pf-dot\"></div>3 physical stickers (one-time purchase)</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>3 gift codes to share with family</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Everything in Standard plan</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Priority support</div>\n    </div>\n    <a href=\"/register.html\" style=\"background:#1A1A1A;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get Premium</a>\n  </div>\n\n  <div style=\"background:#F0FDF4;border:1.5px solid #BBF7D0;border-radius:18px;padding:18px;margin-bottom:12px\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n      <div style=\"font-size:17px;font-weight:800;color:#111\">eTag</div>\n      <div style=\"background:#16A34A;color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:99px\">Free</div>\n    </div>\n    <!-- TMC_PATCH64 -->\n    <div style=\"font-size:12px;color:#15803D;margin-bottom:6px\">Download instantly · Get started in 2 minutes</div>\n    <div style=\"font-size:11px;color:#6B7280;margin-bottom:14px;line-height:1.5\">Free to download. Activate for $1 to experience TapMyCar for 30 days; your chosen plan continues after — see <a href=\"/pricing.html\" style=\"color:#FF6B00\">pricing</a>.</div>\n    <a href=\"/register.html\" style=\"background:#16A34A;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get free eTag</a>\n  </div>\n\n  <div style=\"text-align:center;font-size:12px;color:#6B7280\">\n    <a href=\"/pricing.html\" style=\"color:#FF6B00;font-weight:600;text-decoration:none\">See all plans including Premium and Business </a>\n  </div>\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- TESTIMONIAL -->\n<div class=\"section\" style=\"background:#fff;padding:36px 24px\">\n  <div class=\"section-label\">Real customers</div>\n  <h2 style=\"margin-bottom:20px\">Hear it from people using TapMyCar.</h2>\n  <div data-tmc-reel=\"review\" data-tmc-label=\"\"></div>\n</div>\n\n<div class=\"tape\"></div>\n\n<div class=\"section\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">Early users</div>\n  <h2>People love TapMyCar.</h2>\n  <div class=\"testimonial\">\n    <p>\"Someone left a note on my windshield asking me to move my car. I wish I had TapMyCar then  they could have just scanned and called me directly.\"</p>\n    <div class=\"test-author\">\n      <div class=\"test-av\">M</div>\n      <div>\n        <div class=\"test-name\">Mike R.</div>\n        <div class=\"test-sub\">Connecticut, USA</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- CTA -->\n<div class=\"cta\">\n  <h2>Your car deserves protection.</h2>\n  <p>Privacy for you. Safety for your car. Free to start  takes 2 minutes.</p>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"cta-btn\">Explore TapMyCar</a>\n</div>\n\n<!-- APP DOWNLOAD STICKY -->\n<div style=\"background:#111;padding:16px 24px;display:flex;align-items:center;gap:12px\">\n  <div style=\"width:40px;height:40px;border-radius:10px;background:#FF6B00;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n  </div>\n  <div style=\"flex:1\">\n    <div style=\"font-size:13px;font-weight:700;color:#fff\">TapMyCar App</div>\n    <div style=\"font-size:10px;color:#9CA3AF\">Free  iOS, Android & Web</div>\n  </div>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" style=\"background:#FF6B00;color:#fff;font-size:12px;font-weight:700;padding:8px 16px;border-radius:10px;text-decoration:none\">Get App</a>\n</div>\n\n<!-- TMC_PATCH26_APP_SETTINGS: landing.hero slot (download badges) -->\n<div data-tmc-slot=\"landing.hero\" style=\"padding:20px 24px 8px;display:flex;justify-content:center\"></div>\n\n<!-- TMC_PATCH26_APP_SETTINGS: landing.demo slot (demo video) -->\n<div data-tmc-slot=\"landing.demo\" style=\"padding:24px;display:flex;justify-content:center\"></div>\n\n<!-- FOOTER -->\n<!-- TMC_PATCH26_APP_SETTINGS: landing.footer slot (social + support) -->\n<div data-tmc-slot=\"landing.footer\" style=\"padding:14px 24px 0;text-align:center\"></div>\n<div class=\"footer\">\n  <p style=\"margin-bottom:6px\"><a href=\"/register.html\">Sign up</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/signin.html\">Sign in</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/pricing.html\">Pricing</a></p>\n  <p style=\"margin-bottom:6px\"><a href=\"/privacy.html\">Privacy Policy</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/terms.html\">Terms of Service</a></p>\n  <p> 2026 Praman Tech LLC  Connecticut, USA</p>\n</div>\n<script>\nif ('serviceWorker' in navigator) {\n  navigator.serviceWorker.register('/sw.js');\n}\n</script>\n<!-- TMC_PATCH26_APP_SETTINGS: settings renderer -->\n<script src=\"/app-settings.js\" defer></script>\n\n\n\n<script>\n// Dynamic testimonial loader - replaces fake Mike R. with most recent FEATURED review\n(async function() {\n  try {\n    const res = await fetch('/api/get-reviews?status=approved&landing_only=true&limit=1');\n    const data = await res.json();\n    if (!data.reviews || data.reviews.length === 0) return; // keep Mike R. fallback\n\n    const r = data.reviews[0];\n    const esc = s => String(s || '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\n    // Find the testimonial container\n    const testContainer = document.querySelector('.testimonial');\n    if (!testContainer) return;\n\n    // 1. Replace the quote paragraph (first <p> child of .testimonial)\n    const quoteEl = testContainer.querySelector('p');\n    if (quoteEl) quoteEl.innerHTML = '&quot;' + esc(r.text) + '&quot;';\n\n    // 2. Replace the avatar letter\n    const avEl = testContainer.querySelector('.test-av');\n    if (avEl) avEl.textContent = (r.name || 'U')[0].toUpperCase();\n\n    // 3. Replace name\n    const nameEl = testContainer.querySelector('.test-name');\n    if (nameEl) nameEl.textContent = r.name;\n\n    // 4. Replace city/subtitle (if present)\n    const subEl = testContainer.querySelector('.test-sub');\n    if (subEl) subEl.textContent = r.city || 'Verified user';\n  } catch (e) {\n    // Silent - landing keeps Mike R. fallback\n  }\n})();\n</script>\n<script src=\"/app.js\"></script>\n<script src=\"/tmc-redesign.js\"></script>\n\n<script>\n// TMC_PATCH62_LANDING - logged-in visitors should not be pushed to register.\n(function(){\n  var token = null;\n  try { token = localStorage.getItem(\"tmc_token\"); } catch(e){}\n  if (!token) return;  // logged-out visitor: leave the page as-is\n  var ctas = document.querySelectorAll('a[data-tmc-cta=\"1\"]');\n  for (var i = 0; i < ctas.length; i++) {\n    ctas[i].setAttribute(\"href\", \"/dashboard.html\");\n    var t = (ctas[i].textContent || \"\").trim().toLowerCase();\n    // Relabel the wordy CTAs; leave tiny header buttons compact.\n    if (t.indexOf(\"explore\") !== -1 || t.indexOf(\"download\") !== -1) {\n      ctas[i].textContent = \"Go to Dashboard\";\n    } else {\n      ctas[i].textContent = \"Dashboard\";\n    }\n  }\n})();\n</script>\n<script src=\"/tmc-reels.js\"></script>\n<script>\n/* TMC_BRANDING_PRELOAD: avoid fallback flash via sessionStorage cache */\n(function(){\n  var KEY = 'tmc_hero_sticker_url';\n  var el = document.getElementById('tmc-hero-sticker');\n  if (!el) return;\n  try {\n    var cached = sessionStorage.getItem(KEY);\n    if (cached && cached !== 'null') {\n      el.innerHTML = '<img src=\"' + cached + '\" alt=\"TapMyCar sticker\">';\n    } else if (cached !== 'null') {\n      el.style.visibility = 'hidden';\n    }\n  } catch (e) {}\n  fetch('/api/get-branding').then(function(r){ return r.json(); }).then(function(d){\n    var url = (d && d.ok && d.sticker_url) ? d.sticker_url : null;\n    try { sessionStorage.setItem(KEY, url == null ? 'null' : url); } catch (e) {}\n    el.style.visibility = ''; el.classList.remove('tmc-pre-hidden');\n    if (url) {\n      var cur = el.querySelector('img');\n      if (!cur || cur.src !== url) el.innerHTML = '<img src=\"' + url + '\" alt=\"TapMyCar sticker\">';\n    }\n  }).catch(function(){ el.style.visibility = ''; el.classList.remove('tmc-pre-hidden'); });\n\n  /* Mouse-follow tilt on the sticker scene */\n  var scene = document.getElementById('tmc-hero-scene');\n  var sticker = document.getElementById('tmc-hero-sticker');\n  if (scene && sticker) {\n    var rect = null;\n    scene.addEventListener('mouseenter', function () { rect = scene.getBoundingClientRect(); sticker.style.transition = 'transform .15s ease-out'; });\n    scene.addEventListener('mousemove', function (e) {\n      if (!rect) rect = scene.getBoundingClientRect();\n      var cx = rect.left + rect.width / 2;\n      var cy = rect.top + rect.height / 2;\n      var dx = (e.clientX - cx) / (rect.width / 2);\n      var dy = (e.clientY - cy) / (rect.height / 2);\n      sticker.style.animation = 'none';\n      sticker.style.transform = 'rotateY(' + (dx * 35) + 'deg) rotateX(' + (-dy * 25) + 'deg) translateY(-4px) scale(1.05)';\n    });\n    scene.addEventListener('mouseleave', function () {\n      sticker.style.transition = 'transform .4s cubic-bezier(.2,.8,.2,1)';\n      sticker.style.transform = '';\n      sticker.style.animation = '';\n      rect = null;\n    });\n  }\n\n  /* Ripple on every CTA + step num */\n  function attachRipple(el) {\n    el.style.position = 'relative';\n    el.style.overflow = 'hidden';\n    el.addEventListener('click', function (e) {\n      var r = el.getBoundingClientRect();\n      var ripple = document.createElement('span');\n      var size = Math.max(r.width, r.height) * 2;\n      ripple.style.cssText = 'position:absolute;left:' + (e.clientX - r.left - size/2) + 'px;top:' + (e.clientY - r.top - size/2) + 'px;width:' + size + 'px;height:' + size + 'px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.55),transparent 65%);pointer-events:none;transform:scale(0);animation:tmcRipple .6s ease-out forwards;z-index:1';\n      el.appendChild(ripple);\n      setTimeout(function () { ripple.remove(); }, 650);\n    });\n  }\n  document.querySelectorAll('.hero-btn-primary, .hero-btn-secondary, .app-btn, .cta-btn, [data-tmc-cta]').forEach(attachRipple);\n\n  /* Inject ripple keyframes if not present */\n  if (!document.getElementById('tmc-ripple-style')) {\n    var st = document.createElement('style');\n    st.id = 'tmc-ripple-style';\n    st.textContent = '@keyframes tmcRipple { to { transform: scale(1); opacity: 0; } }\\n' +\n      '.hero-btn-primary, .hero-btn-secondary, .cta-btn, .app-btn, [data-tmc-cta] { transition: transform .2s ease, box-shadow .2s ease; }\\n' +\n      '.hero-btn-primary:hover, .cta-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 14px 32px rgba(0,0,0,.22); }\\n' +\n      '.hero-btn-secondary:hover { transform: translateY(-2px); background: rgba(255,255,255,.25); }\\n' +\n      '.app-btn:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(255,107,0,.5); }\\n' +\n      '[data-tmc-cta]:hover { transform: translateY(-1px) scale(1.03); box-shadow: 0 6px 18px rgba(255,107,0,.45); }\\n' +\n      '.tmc-stat { transition: transform .2s ease; }\\n' +\n      '.tmc-stat:hover { transform: translateY(-3px); }\\n' +\n      '.tmc-stat:hover .tmc-stat-n { color: #FF8420; }\\n' +\n      '.step-num { transition: transform .25s cubic-bezier(.2,.8,.2,1); }\\n' +\n      '.step:hover .step-num { transform: scale(1.15) rotate(-6deg); }\\n' +\n      '.step { transition: transform .25s ease; }\\n' +\n      '.step:hover { transform: translateX(4px); }';\n    document.head.appendChild(st);\n  }\n})();\n\n/* TMC_COMIC: load + run slideshow */\n(function(){\n  fetch('/api/get-comic').then(function(r){ return r.json(); }).then(function(d){\n    var panels = (d && d.panels) || [];\n    var withImg = panels.filter(function(p){ return p && p.image_url; });\n    if (!withImg.length) return;\n    var section = document.getElementById('tmc-comic-section');\n    var panelsBox = document.getElementById('tmc-comic-panels');\n    var progBox = document.getElementById('tmc-comic-prog');\n    var dotsBox = document.getElementById('tmc-comic-dots');\n    if (!section || !panelsBox || !progBox || !dotsBox) return;\n    section.hidden = false;\n    function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }\n    panelsBox.innerHTML = withImg.map(function(p, i){\n      return '<div class=\"tmc-comic-panel\">' +\n        '<div class=\"tmc-comic-art\">' +\n          '<img loading=\"lazy\" src=\"' + esc(p.image_url) + '\" alt=\"\">' +\n          '<div class=\"tmc-comic-overlay\"></div>' +\n          '<div class=\"tmc-comic-num\">FRAME ' + (i+1) + ' / ' + withImg.length + '</div>' +\n          '<div class=\"tmc-comic-cap\">' +\n            (p.title ? '<div class=\"tmc-comic-cap-t\">' + esc(p.title) + '</div>' : '') +\n            (p.caption ? '<div class=\"tmc-comic-cap-s\">' + esc(p.caption) + '</div>' : '') +\n          '</div>' +\n        '</div>' +\n      '</div>';\n    }).join('');\n    progBox.innerHTML = withImg.map(function(){ return '<div class=\"tmc-comic-prog-seg\"><div class=\"fill\"></div></div>'; }).join('');\n    dotsBox.innerHTML = withImg.map(function(_, i){ return '<button type=\"button\" class=\"tmc-comic-dot\" data-idx=\"' + i + '\" aria-label=\"Frame ' + (i+1) + '\"></button>'; }).join('');\n    var panelEls = panelsBox.querySelectorAll('.tmc-comic-panel');\n    var progEls = progBox.querySelectorAll('.tmc-comic-prog-seg');\n    var dotEls = dotsBox.querySelectorAll('.tmc-comic-dot');\n    var cur = 0, timer;\n    function go(i) {\n      cur = (i + panelEls.length) % panelEls.length;\n      panelEls.forEach(function(p, n){ p.classList.toggle('on', n === cur); });\n      dotEls.forEach(function(d, n){ d.classList.toggle('active', n === cur); });\n      progEls.forEach(function(s, n){\n        s.classList.remove('active','done');\n        if (n < cur) s.classList.add('done');\n        if (n === cur) s.classList.add('active');\n      });\n    }\n    function startT(){ clearInterval(timer); timer = setInterval(function(){ go(cur+1); }, 4500); }\n    go(0); startT();\n    document.getElementById('tmc-comic-prev').addEventListener('click', function(){ go(cur-1); startT(); });\n    document.getElementById('tmc-comic-next').addEventListener('click', function(){ go(cur+1); startT(); });\n    dotEls.forEach(function(d, i){ d.addEventListener('click', function(){ go(i); startT(); }); });\n    var startX = null;\n    var stage = document.getElementById('tmc-comic-stage');\n    stage.addEventListener('touchstart', function(e){ startX = e.touches[0].clientX; }, { passive: true });\n    stage.addEventListener('touchend', function(e){\n      if (startX === null) return;\n      var dx = e.changedTouches[0].clientX - startX; startX = null;\n      if (Math.abs(dx) > 40) { go(dx < 0 ? cur+1 : cur-1); startT(); }\n    });\n  }).catch(function(){});\n})();\n\n</script>\n</body>\n</html>\n";

